/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isTitle = require( '@stdlib/plot/vega/base/assert/is-title' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:visualization:set:title' );


// MAIN //

/**
* Sets the visualization title.
*
* ## Notes
*
* -   Providing `undefined` "unsets" the configured value.
*
* @private
* @param {(Title|void)} value - input value
* @throws {TypeError} must be a string
* @returns {void}
*/
function set( value ) {
	if ( !isTitle( value ) && !isUndefined( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a title instance. Value: `%s`.', 'title', value ) );
	}
	if ( value !== this._title ) {
		if ( this._title ) {
			this._title.removeListener( 'change', this._onTitleChange );
		}
		debug( 'Current value: %s. New value: %s.', this._title, value );
		this._title = value;
		this.emit( 'change' );
		if ( this._title ) {
			this._title.on( 'change', this._onTitleChange );
		}
	}
}


// EXPORTS //

module.exports = set;
